"""The daemon's generated files: its HTTP routes, their JSON codec, and the API's OpenAPI document."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from .ai_codec import generate_ai_codec
from .ai_routes import generate_ai_routes
from .generate import Model
from .http_routes import generate_routes
from .json_codec import generate_codec
from .openapi import document, dumps, merge
from .routes import Contract

# Included as the daemon includes them: core's C++ declarations from its SDK, the codec beside the routes.
API_HEADER = "api/Contract.h"
CODEC_HEADER = "api/generated/ContractJson.h"
# Where make -C contract update writes them, relative to the repository.
DAEMON_PATHS = {"ContractJson.h": "daemon/src/api/generated/ContractJson.h",
                "ContractRoutes.h": "daemon/src/api/generated/ContractRoutes.h",
                "AiJson.h": "daemon/src/api/generated/AiJson.h",
                "AiRoutes.h": "daemon/src/api/generated/AiRoutes.h"}
# The API's metadata and security, shared by every route in the contract.
OPENAPI_BASE = "api/openapi-base.json"
OPENAPI_PATHS = {"openapi.yaml": "api/openapi.yaml", "openapi.json": "api/openapi.json"}
YAML_HEADER = ("# Generated by holder_contract from contract/ and api/openapi-base.json;\n"
               "# edit those, then run make -C contract update. Do not edit this file.\n")


def generate_daemon(ir: dict[str, Any], contract: Contract) -> dict[str, str]:
    """The generated files, by name, with the contract's OpenAPI paths on their own."""
    model = Model(ir)
    return {"ContractJson.h": generate_codec(model, API_HEADER),
            "ContractRoutes.h": generate_routes(model, CODEC_HEADER),
            "AiJson.h": generate_ai_codec(ir, contract),
            "AiRoutes.h": generate_ai_routes(ir),
            "openapi.json": dumps(document(contract))}


def api_documents(contract: Contract, repository: Path) -> dict[str, str]:
    """The API's OpenAPI document, as YAML and JSON: metadata and contract routes together."""
    base = json.loads((repository / OPENAPI_BASE).read_text(encoding="utf-8"))
    merged = merge(base, document(contract))
    return {"openapi.yaml": YAML_HEADER + dumps(merged, "yaml"), "openapi.json": dumps(merged)}
